export type LostDomainsCopy = Omit<typeof en, "outcomes" | "riskReasons"> & {
  outcomes: Record<string, string>;
  riskReasons: Record<string, string>;
};
export function getLostDomainsCopy(language: string): LostDomainsCopy {
  if (language === "sv") return sv;
  if (language === "es") return es;
  if (language === "fr") return fr;
  if (language === "zh") return zh;
  return en;
}

